public class AppendSingleSkill
{
    public static void Execute(string chart_id, string x_value, string y_value)
    {
        Debug.Log("Executing AppendSingleSkill...");

        GameObject visObj = GameObject.Find(chart_id);
        if (visObj == null)
        {
            Debug.LogWarning("Chart not found: " + chart_id);
            return;
        }

        Vis vis = visObj.GetComponent<Vis>();
         if (vis == null)
        {
            Debug.LogWarning("Vis component not found on: " + chart_id);
         return;
        }

        JSONNode visSpecs = vis.GetVisSpecs();
        if (visSpecs == null)
        {
  Debug.LogWarning("Vis specs is null for chart: " + chart_id);
            return;
        }

        string xField = null;
        if (visSpecs["encoding"] != null && visSpecs["encoding"]["x"] != null && visSpecs["encoding"]["x"]["field"] != null)
        {
            xField = visSpecs["encoding"]["x"]["field"].Value;
        }

        string yField = null;
        if           (visSpecs["encoding"] != null && visSpecs["encoding"]["y"] != null && visSpecs["encoding"]["y"]["field"] != null)
        {
            yField = visSpecs["encoding"]["y"]["field"].Value;
        }

        if (xField == null || yField == null)
     {
            Debug.LogWarning("Missing x or y field mapping in vis spec encoding for chart: " + chart_id);
  return;
        }

        Dictionary<string, string> newDatum = new Dictionary<string, string>();
           foreach (string field in vis.data.fieldNames)
        {
            newDatum[field] = "0";
        }
       newDatum[xField] = x_value;
        newDatum[yField] = y_value;

        vis.data.values.Add(newDatum);

    JSONNode dataValues = visSpecs["data"]["values"];
        if (dataValues != null)
        {
               JSONObject newEntry = new JSONObject();
            foreach (string field in vis.data.fieldNames)
              {
                newEntry[field] = new JSONString(newDatum[field]);
            }
                            dataValues.Add(newEntry);
        }

        if (vis.markInstances.Count > 0)
        {
                     GameObject templateMark = vis.markInstances[vis.markInstances.Count - 1];
            Transform parent = templateMark.transform.parent;
            GameObject newMark = GameObject.Instantiate(templateMark, parent);
  Mark markComponent = newMark.GetComponent<Mark>();
            if (markComponent != null)
            {
       markComponent.datum = newDatum;
                markComponent.SetChannelValue("x", x_value);
                 markComponent.SetChannelValue("y", y_value);
            }
            vis.markInstances.Add(newMark);
      }

        if (visSpecs["data"]["url"] != null && visSpecs["data"]["url"].Value != "inline")
        {
            string dataFilePath = Parser.GetFullDataPath(visSpecs["data"]["url"].Value);
            if   (File.Exists(dataFilePath))
            {
                string dataContent = File.ReadAllText(dataFilePath);
                JSONNode dataFileJson = JSON.Parse(dataContent);
               if (dataFileJson != null)
                {
                    JSONObject appendEntry = new JSONObject();
    foreach (string field in vis.data.fieldNames)
                    {
                        appendEntry[field] = new JSONString(newDatum[field]);
                    }
                    dataFileJson.Add(appendEntry);
   File.WriteAllText(dataFilePath, dataFileJson.ToString(2));
                }
            }
        }
         else
        {
            string specFilePath = Parser.GetFullSpecsPath(vis.visSpecsURL);
 JSONNode visSpecsToWrite = JSON.Parse(visSpecs.ToString());
            File.WriteAllText(specFilePath, visSpecsToWrite.ToString(2));
        }

        Debug.Log("AppendSingleSkill completed: chart=" + chart_id + " x=" + x_value + " y=" + y_value);
    }
}

using UnityEngine;
using DxR;
using SimpleJSON;
using System.Collections.Generic;
using System.IO;

public class AppendSeriesSkill
{
    public static void Execute(string chart_id, List<string> x_values, List<string> y_values, int serie_index)
    {
        Debug.Log("Executing AppendSeriesSkill...");

        GameObject visObj = GameObject.Find(chart_id);
        if (visObj == null) { Debug.LogWarning("Chart not found: " + chart_id); return; }
        Vis vis = visObj.GetComponent<Vis>();
        if (vis == null) { Debug.LogWarning("Vis component not found on: " + chart_id); return; }

        if (x_values == null || y_values == null || x_values.Count != y_values.Count)
        {
            Debug.LogWarning("x_values and y_values must be non-null and have the same length.");
            return;
        }

        JSONNode specs = vis.GetVisSpecs();
        if (specs == null) { Debug.LogWarning("Vis specs not found."); return; }

        string visSpecsURL = specs["data"]["url"].Value;
        if (string.IsNullOrEmpty(visSpecsURL)) { Debug.LogWarning("Data URL not found in vis specs."); return; }

        string jsonFilePath = Path.Combine(Application.streamingAssetsPath, visSpecsURL);
        if (!File.Exists(jsonFilePath)) { Debug.LogWarning("JSON file not found: " + jsonFilePath); return; }

        string jsonContent = File.ReadAllText(jsonFilePath);
        JSONNode jsonData = JSON.Parse(jsonContent);
        if (jsonData == null) { Debug.LogWarning("Failed to parse JSON file."); return; }

        string xField = specs["encoding"]["x"]["field"].Value;
        string yField = specs["encoding"]["y"]["field"].Value;
        if (string.IsNullOrEmpty(xField) || string.IsNullOrEmpty(yField))
        {
            Debug.LogWarning("x or y field mapping not found in encoding.");
            return;
        }

        string serieField = "";
        if (specs["encoding"]["color"] != null && specs["encoding"]["color"]["field"] != null)
        {
            serieField = specs["encoding"]["color"]["field"].Value;
        }

        JSONArray valuesArray = jsonData["values"].AsArray;
        if (valuesArray == null)
        {
            valuesArray = new JSONArray();
            jsonData["values"] = valuesArray;
        }

        string serieValue = serie_index.ToString();
        if (!string.IsNullOrEmpty(serieField))
        {
            HashSet<string> existingSeries = new HashSet<string>();
            for (int i = 0; i < valuesArray.Count; i++)
            {
                string sv = valuesArray[i][serieField].Value;
                if (!existingSeries.Contains(sv)) existingSeries.Add(sv);
            }
            List<string> sortedSeries = new List<string>(existingSeries);
            sortedSeries.Sort();
            if (serie_index >= 0 && serie_index < sortedSeries.Count)
            {
                serieValue = sortedSeries[serie_index];
            }
        }

        for (int i = 0; i < x_values.Count; i++)
        {
            JSONNode newEntry = new JSONObject();
            newEntry[xField] = x_values[i];
            newEntry[yField] = y_values[i];
            if (!string.IsNullOrEmpty(serieField))
            {
                newEntry[serieField] = serieValue;
            }
            valuesArray.Add(newEntry);
        }

        jsonData["values"] = valuesArray;
        File.WriteAllText(jsonFilePath, jsonData.ToString());

        vis.UpdateVis();

        Debug.Log("AppendSeriesSkill completed. Appended " + x_values.Count + " data points to serie " + serie_index + ".");
    }
}

