public class HighlightSkill
{
    public static void Execute(string chart_id, string element_id, string highlight_type)
    {
        Debug.Log("Executing HighlightSkill...");

        GameObject visObj = GameObject.Find(chart_id);
        if (visObj == null) { Debug.LogWarning("Chart not found: " + chart_id); return; }
        Vis vis = visObj.GetComponent<Vis>();
        if (vis == null) { Debug.LogWarning("Vis component not found on: " + chart_id); return; }

        int index;
        if (!int.TryParse(element_id, out index))
        {
            Debug.LogWarning("Invalid element_id: " + element_id);
            return;
        }

        if (index < 0 || index >= vis.markInstances.Count)
        {
            Debug.LogWarning("element_id out of range: " + element_id);
            return;
        }

        JSONNode specs = vis.GetVisSpecs();
        if (specs == null) { Debug.LogWarning("Vis specs not found."); return; }

        string visSpecsURL = specs["data"]["url"].Value;
        if (string.IsNullOrEmpty(visSpecsURL)) { Debug.LogWarning("Data URL not found in vis specs."); return; }

        string jsonFilePath = Path.Combine(Application.streamingAssetsPath, visSpecsURL);
        if (!File.Exists(jsonFilePath)) { Debug.LogWarning("JSON file not found: " + jsonFilePath); return; }

        string jsonContent = File.ReadAllText(jsonFilePath);
        JSONNode jsonData = JSON.Parse(jsonContent);
        if (jsonData == null) { Debug.LogWarning("Failed to parse JSON file."); return; }

        JSONArray valuesArray = jsonData["values"].AsArray;
        if (valuesArray == null || index >= valuesArray.Count)
        {
            Debug.LogWarning("Values array is null or index out of range.");
            return;
        }

        string highlightField = "_highlight";

        switch (highlight_type.ToLower())
        {
            case "color":
                for (int i = 0; i < valuesArray.Count; i++)
                {
                    valuesArray[i][highlightField] = (i == index) ? "true" : "false";
                }
                Mark targetMark = vis.markInstances[index].GetComponent<Mark>();
                if (targetMark != null)
                {
                    targetMark.SetChannelValue("color", "#ffff00");
                    targetMark.datum[highlightField] = "true";
                }
                for (int i = 0; i < vis.markInstances.Count; i++)
                {
                    if (i == index) continue;
                    Mark m = vis.markInstances[i].GetComponent<Mark>();
                    if (m != null) m.datum[highlightField] = "false";
                }
                break;

            case "scale":
                for (int i = 0; i < valuesArray.Count; i++)
                {
                    valuesArray[i][highlightField] = (i == index) ? "true" : "false";
                }
                vis.markInstances[index].transform.localScale *= 1.5f;
                Mark scaleMark = vis.markInstances[index].GetComponent<Mark>();
                if (scaleMark != null) scaleMark.datum[highlightField] = "true";
                for (int i = 0; i < vis.markInstances.Count; i++)
                {
                    if (i == index) continue;
                    Mark sm = vis.markInstances[i].GetComponent<Mark>();
                    if (sm != null) sm.datum[highlightField] = "false";
                }
                break;

            case "opacity":
                for (int i = 0; i < valuesArray.Count; i++)
                {
                    valuesArray[i][highlightField] = (i == index) ? "true" : "false";
                }
                for (int i = 0; i < vis.markInstances.Count; i++)
                {
                    Mark m = vis.markInstances[i].GetComponent<Mark>();
                    if (m != null)
                    {
                        m.SetChannelValue("opacity", i == index ? "1.0" : "0.3");
                        m.datum[highlightField] = (i == index) ? "true" : "false";
                    }
                }
                break;

            case "none":
                for (int i = 0; i < valuesArray.Count; i++)
                {
                    valuesArray[i].Remove(highlightField);
                }
                for (int i = 0; i < vis.markInstances.Count; i++)
                {
                    Mark m = vis.markInstances[i].GetComponent<Mark>();
                    if (m != null)
                    {
                        m.SetChannelValue("opacity", "1.0");
                        if (m.datum.ContainsKey(highlightField)) m.datum.Remove(highlightField);
                    }
                    vis.markInstances[i].transform.localScale = Vector3.one;
                }
                break;

            default:
                Debug.LogWarning("Unknown highlight_type: " + highlight_type + ". Use: color, scale, opacity, none.");
                return;
        }

        jsonData["values"] = valuesArray;
        File.WriteAllText(jsonFilePath, jsonData.ToString());

        vis.UpdateVis();

        Debug.Log("HighlightSkill completed. Element " + element_id + " highlighted with type: " + highlight_type);
    }
}
